import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_LEVEL = 7;
    static final int MAX_VAL = 1000000;
    static final int MOD1 = 998244353;
    static final int MOD2 = 1000000007;
    static long total_input, total_count;
    static List<Integer>[] number_sets = new ArrayList[MAX_LEVEL];
    static int result_value, prefix_sum_vals[] = new int[MAX_LEVEL];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total_input = Long.parseLong(br.readLine());
        for (int i = 0; i < MAX_LEVEL; i++) {
            number_sets[i] = new ArrayList<>();
        }

        // Build tree function
        build_tree(0, 0);

        // Sorting and prefix sums
        for (int d = 0; d <= 6; d++) {
            Collections.sort(number_sets[d]);
            for (int v : number_sets[d]) {
                prefix_sum_vals[d] = (int)((prefix_sum_vals[d] + v) % MOD2);
            }
        }

        result_value = 0;
        total_count = 0;
        traverse_tree(0, 0L);

        System.out.println(result_value);
    }

    static void build_tree(int level, int val) {
        total_count++;
        number_sets[level].add((int)((total_count - val + MOD1) % MOD1));
        if (level == 6) return;
        for (int digit = 0; digit < 10; digit++) {
            build_tree(level + 1, val * 10 + digit);
        }
    }

    static void traverse_tree(int depth, long v) {
        if (v > total_input) return;
        if (depth != 0) {
            if (v * MAX_VAL > total_input / 10 && (v + 1) * MAX_VAL - 1 <= total_input) {
                for (int i = 0, pwr = 1; i <= 6; i++, pwr *= 10) {
                    int coef = (int)((total_count - (long)v * pwr % MOD1 + MOD1) % MOD1);
                    List<Integer> arr = number_sets[i];
                    int idx = lowerBound(arr, MOD1 - coef);
                    result_value = (int)((result_value + 1L * coef * arr.size() + prefix_sum_vals[i]) % MOD2);
                    int countGreater = arr.size() - idx;
                    result_value = (int)((result_value - 1L * MOD1 * countGreater % MOD2 + MOD2) % MOD2);
                }
                for (int i = 0; i <= 6; i++) {
                    total_count += number_sets[i].size();
                }
                return;
            }
            result_value = (int)((result_value + (total_count - v % MOD1 + MOD1) % MOD1) % MOD2);
        }
        for (int c = (depth == 0 ? 1 : 0); c < 10; c++) {
            traverse_tree(depth + 1, v * 10 + c);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
